```yaml
name: PR Commit Security Scan

on:
  pull_request:
    types: [opened, synchronize, reopened]

permissions:
  contents: read
  issues: write

jobs:
  brin-scan:
    runs-on: ubuntu-latest
    steps:
      - name: Checkout repository
        uses: actions/checkout@v4
        with:
          fetch-depth: 0

      - name: Set up Node.js
        uses: actions/setup-node@v4
        with:
          node-version: '20'

      - name: Install Brin CLI
        run: npm install -g @brin/cli

      - name: Scan PR commits with Brin
        id: scan
        run: |
          #!/usr/bin/env bash
          set -euo pipefail

          PR_NUMBER=${{ github.event.pull_request.number }}
          BRANCH=pr-${PR_NUMBER}
          git fetch origin pull/${PR_NUMBER}/head:${BRANCH}
          git checkout ${BRANCH}

          COMMITS=$(git rev-list --reverse ${BRANCH})
          echo "Commits to scan: ${COMMITS}"

          RESULTS=()
          FAIL=0

          for COMMIT in ${COMMITS}; do
            git checkout ${COMMIT}
            echo "Scanning commit ${COMMIT}"
            MSG=$(git log -1 --pretty=%s)
            BRIN_OUTPUT=$(brin scan --output json 2>&1 || true)
            BLOCKING=$(echo "${BRIN_OUTPUT}" | jq -r '.blocking // 0')
            REVIEW=$(echo "${BRIN_OUTPUT}" | jq -r '.review // 0')
            INCONCLUSIVE=$(echo "${BRIN_OUTPUT}" | jq -r '.inconclusive // 0')
            SCORE=$(echo "${BRIN_OUTPUT}" | jq -r '.score // 0')
            RESULTS+=("{\"sha\":\"${COMMIT}\",\"msg\":\"${MSG}\",\"blocking\":${BLOCKING},\"review\":${REVIEW},\"inconclusive\":${INCONCLUSIVE},\"score\":${SCORE}}")
            if (( BLOCKING > 0 || SCORE < 30 )); then
              FAIL=1
            fi
          done

          BODY="## Brin Security Scan\n\n"
          for RES in "${RESULTS[@]}"; do
            SHA=$(echo "${RES}" | jq -r '.sha')
            MSG=$(echo "${RES}" | jq -r '.msg')
            BLOCKING=$(echo "${RES}" | jq -r '.blocking')
            REVIEW=$(echo "${RES}" | jq -r '.review')
            INCONCLUSIVE=$(echo "${RES}" | jq -r '.inconclusive')
            SCORE=$(echo "${RES}" | jq -r '.score')
            BODY+="### Commit: ${SHA} ${MSG}\n"
            BODY+="- Blocking: ${BLOCKING}\n"
            BODY+="- Review: ${REVIEW}\n"
            BODY+="- Inconclusive: ${INCONCLUSIVE}\n"
            BODY+="- Score: ${SCORE}\n\n"
          done

          echo "${BODY}" > /tmp/brin_comment.txt
          echo "${FAIL}" > /tmp/brin_fail.txt
          echo "fail=${FAIL}" >> $GITHUB_OUTPUT
        shell: bash

      - name: Update PR comment
        uses: actions/github-script@v6
        with:
          script: |
            const fs = require('fs');
            const body = fs.readFileSync('/tmp/brin_comment.txt', 'utf8');
            const fail = fs.readFileSync('/tmp/brin_fail.txt', 'utf8').trim() === '1';
            const prNumber = context.issue.number;
            const comments = await github.rest.issues.listComments({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: prNumber,
            });
            const targetComment = comments.data.find(c => c.body.includes('## Brin Security Scan'));
            if (fail) {
              if (targetComment) {
                await github.rest.issues.updateComment({
                  owner: context.repo.owner,
                  repo: context.repo.repo,
                  comment_id: targetComment.id,
                  body: body,
                });
              } else {
                await github.rest.issues.createComment({
                  owner: context.repo.owner,
                  repo: context.repo.repo,
                  issue_number: prNumber,
                  body: body,
                });
              }
            } else {
              if (targetComment) {
                await github.rest.issues.deleteComment({
                  owner: context.repo.owner,
                  repo: context.repo.repo,
                  comment_id: targetComment.id,
                });
              }
            }
        env:
          GITHUB_TOKEN: ${{ secrets.GITHUB_TOKEN }}

      - name: Fail job if dangerous
        if: ${{ steps.scan.outputs.fail == '1' }}
        run: exit 1
